using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.Condominios;using GraphApi.Services.SGR.Condominios;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.Condominios{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Condominios: creación, actualización y eliminación.")]    public class CondominiosMutation    {        [Authorize]        [GraphQLName("createCondominios")]        [GraphQLDescription("Crea un nuevo Condominio usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadCondominios> CreateCondominiosAsync(            [GraphQLDescription("Datos necesarios para crear el Condominio.")]            clCreateCondominios objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Condominio.")]            ICondominiosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateCondominios(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateCondominios")]        [GraphQLDescription("Actualiza los campos especificados de un Condominio existente.")]        public async Task<clReadCondominios?> UpdateCondominiosAsync(            [GraphQLDescription("Datos del Condominio a actualizar.")]            clUpdateCondominios objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Condominio.")]            ICondominiosService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateCondominios(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteCondominios")]        [GraphQLDescription("Elimina un Condominio por su ID.")]        public async Task<bool> delCondominiosAsync(            [GraphQLDescription("ID del Condominio a eliminar.")]            int nCondominiosID,            [Service]            [GraphQLDescription("Servicio para operaciones de Condominio.")]            ICondominiosService objService        )        {            return await objService.DeleteCondominios(nCondominiosID);        }    }}